css:
[data-bz-node="cf-row"] { gap: 48px; align-items: stretch; }
[data-bz-node="cf-form"] .bz-form { padding: 32px; }
[data-bz-node="contact-mapcol"] { min-height: 420px; display: flex; }
[data-bz-node="contact-map"], [data-bz-node="contact-map"] .bz-widget { flex: 1; display: flex; flex-direction: column; margin: 0; }
[data-bz-node="contact-map"] .bz-map { flex: 1; min-height: 420px; border: 1px solid var(--line); border-radius: var(--radius-card); overflow: hidden; background: var(--hcm-tint); }
[data-bz-node="contact-map"] .bz-loclist, [data-bz-node="contact-map"] .bz-widget__empty { display: none; }
@media (max-width: 900px) { [data-bz-node="cf-row"] > .bz-col { grid-column: 1 / -1; } }
